    FROM acdoca_data
    LEFT JOIN sales_data ON try_to_number(acdoca_data.ACDOCA_ASSIGNMENT_NUMBER) = try_to_number(sales_data.VBAK_SALES_DOCUMENT)
    LEFT JOIN business_data ON
        sales_data.VBAP_SALES_DOCUMENT = VBKD_SALES_AND_DISTRIBUTION_DOCUMENT_NUMBER AND
        (sales_data.SALES_DOCUMENT_ITEM_POSNR = VBKD_ITEM_NUMBER_OF_THE_SD_DOCUMENT OR VBKD_ITEM_NUMBER_OF_THE_SD_DOCUMENT='000000')
),

